const res = await tools.hold_arm({
  first: { plan: "plan-a", phase: "A1" },
  second: { plan: "plan-b", phase: "B1" },
  leading: "plan-a",
  reason: "Both active phases rewrite the same `HitRecord` struct and the same `Sphere::hit` record construction in `src/hittable.rs` and `src/sphere.rs`: A1 adds `material: Rc<dyn Material>`, drops `Copy` and builds `HitRecord { ... }`, while B1 adds `front_face`/`u`/`v` and requires every shape to build the record only through the new `HitRecord::new`, which has no material parameter. A mechanical merge would leave a struct-literal path beside the sole constructor and a missing/duplicated material field, so the two must settle a shared record shape and constructor signature; that overlap also moves the outward normal A2's glass work depends on, so it must be fixed before A1 codes."
});
return res;

return await tools.hold_arm({
  first: { plan: "plan-a", phase: "A2" },
  second: { plan: "plan-b", phase: "B2" },
  leading: "plan-a",
  reason: "Both branches have already rewritten the same contract in `src/hittable.rs` and `src/sphere.rs`: plan-a's `HitRecord` carries `Rc<dyn Material>` with no `Copy`, while plan-b's carries `front_face`/`u`/`v` and is built only through `HitRecord::new`, and neither struct can be the other's base. Merging needs one combined record (material plus face side plus u/v, one constructor or struct literal), and B2's new `Plane`/`Triangle` in `src/plane.rs`/`src/triangle.rs` already assume B1's material-less `HitRecord::new` while A2 depends on the ray-facing normal B1 added, so both next phases would code on an unsettled shape. A2 and B2 are the first not-started phases on each side; both plans' overlapping work is equally far along, so the leader is the plan the caller names first."
});

